-- Generated by Superwhisper settings.
if package.loaded["superwhisper.shortcuts"] then return end
package.loaded["superwhisper.shortcuts"] = true
local pipe = assert(io.popen("exec env SUPERWHISPER_RUNTIME='/run/user/1000/superwhisper' '/opt/superwhisper/run.sh' shortcut-bridge", 'w'))
pipe:setvbuf('no')
-- The recording overlays animate themselves; Hyprland's layer fade on top
-- would hold back each one's appearance (app/tests/hyprland_overlay_animation.py).
hl.layer_rule({ match = { namespace = "^(superwhisper-edge-glow|superwhisper-indicator)$" }, no_anim = true, animation = "none" })
-- Shortcut edges and correction-window key events cross the local pipe.
-- Keys are observed, not consumed (a hold on Alt alone is the exception; see bind).
local active, last_code, serial = nil, nil, 0
local cancel_pending = nil
local modifiers = {}
local caps_lock = false
local modifier_codes = {[42]=true,[54]=true,[29]=true,[97]=true,[56]=true,[100]=true,[125]=true,[126]=true}
-- Omarchy starts and stops push-to-talk on F9 and Right Alt with a press and a
-- release binding, and Hyprland skips a release binding once another key or a
-- mouse button was released during the hold (KeybindManager::shadowKeybinds).
-- Under Omarchy, report those keys' own edges: the daemon stops a recording
-- that one of them started when it comes up (shortcuts::PushToTalk).
local push_to_talk = type(o) == 'table' and {[67]=true,[100]=true} or {}
local push_to_talk_chords = {F9=67, ['ALT+ALT_R']=100}
local function emit(id, edge, token)
  pipe:write(string.format('{"version":1,"command":"shortcut_event","id":"%s","edge":"%s","token":"%s"}\n', id, edge, token))
  pipe:flush()
end
hl.on('input.keyboard.key', function(code, time, state)
  -- Hyprland's Lua event exposes XKB codes; the table uses evdev codes.
  code = code - 8
  if code == 58 and state == 1 then caps_lock = not caps_lock end
  if modifier_codes[code] then modifiers[code] = state == 1 and true or nil end
  if state ~= 0 then
    local mask = caps_lock and 16 or 0
    if modifiers[42] or modifiers[54] then mask = mask + 1 end
    if modifiers[29] or modifiers[97] then mask = mask + 2 end
    if modifiers[56] or modifiers[100] then mask = mask + 4 end
    if modifiers[125] or modifiers[126] then mask = mask + 8 end
    local window = hl.get_active_window()
    local address = window and window.address or ''
    pipe:write(string.format('{"version":1,"command":"auto_vocabulary_key","code":%d,"modifiers":%d,"address":%q}\n', code, mask, address))
    pipe:flush()
  end
  if state == 1 and (code == 28 or code == 96) and next(modifiers) == nil then
    pipe:write('{"version":1,"command":"auto_vocabulary_submit"}\n')
    pipe:flush()
  end
  if push_to_talk[code] and (state == 0 or state == 1) then
    pipe:write(string.format('{"version":1,"command":"push_to_talk_key","code":%d,"edge":"%s"}\n', code, state == 1 and 'down' or 'up'))
    pipe:flush()
  end
  if state == 1 then last_code = code end
  if cancel_pending then
    if state == 0 and code == cancel_pending then
      emit('cancel', 'down', 'cancel')
      cancel_pending, active = nil, nil
    elseif state == 1 and code ~= cancel_pending then cancel_pending = nil end
  end
  if not active then return end
  if state == 0 and code == active.code then
    emit(active.id, 'up', active.token)
    active = nil
  elseif state == 1 and code ~= active.code and active.solo and not active.interrupted then
    -- Another key may make this a chord. The daemon discards the gesture only
    -- before it has started recording; keep tracking so release still stops it.
    emit(active.id, 'interrupt', active.token)
    active.interrupted = true
  end
end)
-- Omarchy lists its dictation keys (F9, Super+Ctrl+X, and Right Alt on newer
-- Omarchy) in o.dictation_keys. Those keys only ever reach the chosen
-- dictation provider, so when a Superwhisper shortcut uses one, Superwhisper
-- takes the key over instead of both firing. Any other binding on a key is
-- refused when saving, and saving rolls back if one is still there after the
-- reload (an Omarchy without o.dictation_keys). One hl.unbind per key:
-- unbinding a key's press and release handles one by one crashes Hyprland 0.56.
local function chord_id(chord)
  local parts = {}
  for part in chord:gmatch('[^+]+') do parts[#parts + 1] = part:gsub('%s', ''):upper() end
  local key = table.remove(parts)
  table.sort(parts)
  parts[#parts + 1] = key
  return table.concat(parts, '+')
end
local function take_over(chord)
  local owned = type(o) == 'table' and o.dictation_keys
  if type(owned) ~= 'table' then return end
  for keys in pairs(owned) do
    if chord_id(keys) == chord_id(chord) then
      hl.unbind(keys)
      owned[keys] = nil
    end
  end
end
-- Omarchy's dictation keys, as chord_id spells them. An Omarchy that no longer
-- hands them over (no o.dictation_keys) keeps binding them to the selected
-- provider, which is Superwhisper whenever this file is loaded, so a shortcut
-- on one of them is already Superwhisper's: binding it again would fire twice.
local omarchy_dictation = {['F9']=true, ['ALT+ALT_R']=true, ['CTRL+SUPER+X']=true}
-- A mouse button's release reaches no Lua event, so a release binding reports
-- it. Transparent, so no binding shadows it: from Hyprland 0.57 the button's
-- own press binding did (shadowBinds after a consuming press), and the hold
-- never ended. One per button, whatever the modifiers, so letting go of Super
-- before the button still stops.
local released = {}
local function bind_release(button)
  if released[button] then return end
  released[button] = true
  hl.bind(button, function()
    if active and active.code == button then
      emit(active.id, 'up', active.token)
      active = nil
    end
  end, {description='Superwhisper: release', release=true, non_consuming=true, ignore_mods=true, transparent=true})
end
local function bind(id, chord, solo, cancel)
  if type(o) == 'table' and type(o.dictation_keys) ~= 'table' and omarchy_dictation[chord_id(chord)] then return end
  take_over(chord)
  -- A key Superwhisper binds is no longer Omarchy's push-to-talk key.
  local taken = push_to_talk_chords[chord_id(chord)]
  if taken then push_to_talk[taken] = nil end
  -- Keys are observed, not consumed, so a lone modifier still works for
  -- everything else -- except a hold on Alt alone. Apps would see it as a
  -- lone Alt tap, and Electron apps (Slack, Discord, VS Code) and Firefox then
  -- focus their menu bar, so the dictation lands in the File menu. That key is
  -- consumed: Alt+key combinations still reach apps with Alt held (Hyprland
  -- keeps the modifier state), and AltGr layouts never match `Alt_R`.
  local lone_alt = solo and chord:match('Alt_[LR]$') ~= nil
  -- A mouse button stands in for a key code: no key event ever matches it.
  local button = chord:match('mouse:%d+$')
  if button and not cancel then bind_release(button) end
  hl.bind(chord, function()
    -- A physical modifier's press can precede its modifier-mask update.
    -- Match that key independently of the mask, but reject other held modifiers.
    if solo then
      for code in pairs(modifiers) do if code ~= last_code then return end end
    end
    if cancel then
      if solo then cancel_pending = last_code; return end
      emit('cancel', 'down', 'cancel')
      active = nil
      return
    end
    if active then return end
    serial = serial + 1
    active = {id=id, token=tostring(serial), code=button or last_code, solo=solo}
    emit(id, 'down', active.token)
  end, {description='Superwhisper: '..id, non_consuming=(solo and not lone_alt) or cancel, ignore_mods=solo or (cancel and chord == 'Escape')})
end
bind("toggle", "CTRL+ALT+space", false, false)
bind("cancel", "Escape", false, true)
